/**
 * Rebuild Base44 standalone backend entrypoints from preserved editable sources.
 * Base44 redeploy-function stores compiled output as entry.ts; preserve source separately.
 * Only bundle.ts is regenerated by this script; publish functions with the Base44 API.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, resolve, basename, dirname } from 'node:path';
import { build } from 'esbuild';

const root = resolve('base44/functions');
const sourceRoot = resolve('scripts/base44-function-sources');
let count = 0;
for (const name of readdirSync(sourceRoot)) {
  const source = join(sourceRoot, name, 'entry.ts');
  const folder = join(root, name);
  const configPath = join(folder, 'function.jsonc');
  const canonicalEntry = join(folder, 'entry.ts');
  if (!existsSync(source) || !existsSync(configPath) || !existsSync(canonicalEntry)) continue;
  const compiled = await build({
    entryPoints: [canonicalEntry],
    bundle: true,
    platform: 'neutral',
    format: 'esm',
    target: 'es2022',
    packages: 'external',
    write: false,
    logLevel: 'silent',
    plugins: [{name:'editable-sources',setup(buildApi){
      buildApi.onLoad({filter:/[\\/]base44[\\/]functions[\\/][^\\/]+[\\/]entry\.ts$/}, args => {
        const saved=join(sourceRoot, basename(dirname(args.path)), 'entry.ts');
        return { contents: readFileSync(saved,'utf8'), loader:'ts' };
      });
    }}],
  });
  const body = compiled.outputFiles[0].text;
  if (/(?:from\s*|import\s*)["']\.\.\//.test(body)) throw Error('Invalid cross-parent import: '+name);
  writeFileSync(join(folder, 'bundle.ts'), body);
  const config=JSON.parse(readFileSync(configPath, 'utf8'));
  config.entry='bundle.ts';
  writeFileSync(configPath,JSON.stringify(config,null,2)+'\n');
  count++;
}
console.log('Built standalone backend packages:',count);
